define(['jquery','Magento_Ui/js/model/messageList','PayPal_Braintree/js/model/full-screen-loader'],function($,globalMessageList,defaultFullScreenLoader){'use strict';return{fullScreenLoader:defaultFullScreenLoader,validators:[],setFullScreenLoader:function(fullScreenLoader){this.fullScreenLoader=fullScreenLoader;},getFullScreenLoader:function(){return this.fullScreenLoader;},add:function(validator){if(!validator.hasOwnProperty('isEnabled')||typeof validator.isEnabled!=='function'||!validator.isEnabled()){return;}
this.validators.push(validator);},validate:function(context,callback,errorCallback){let self=this,deferred;if(!self.validators.length){callback();return;}
deferred=$.map(self.validators,function(current){return current.validate(context);});$.when.apply($,deferred).done(function(){callback();}).fail(function(error){errorCallback();self.showError(error);});},showError:function(errorMessage){if($('.checkout-index-index').length){globalMessageList.addErrorMessage({message:errorMessage});}else{alert(errorMessage);}
this.getFullScreenLoader().stopLoader(true);}};});